async function retry(fn, { times = 3, delayMs = 100 } = {}) {
  return fn();
}

solutionCodeJson.code:
// Bài 13.4 — retry: thử lại tối đa times lần, chờ delayMs GIỮA các lần, ném lỗi cuối nếu hết lượt
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function retry(fn, { times = 3, delayMs = 100 } = {}) {
  let lastError;
  for (let attempt = 1; attempt <= times; attempt++) {
    try {
      return await fn();                       // await: bắt được cả promise bị từ chối
    } catch (e) {
      lastError = e;
      if (attempt < times) await sleep(delayMs);   // không chờ sau lần cuối
    }
  }
  throw lastError;
}
